create table public.exam_items (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams(id) on delete cascade, sequence integer not null check (sequence > 0), item_type text not null, prompt text not null, configuration jsonb, points numeric(6,2) not null default 1 check (points >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (exam_id, sequence));;
